var myApp={init:function(){myApp.responsiveMenu(),myApp.sliders(),myApp.sortCatalog(),myApp.drawChart()},responsiveMenu:function(){var t=$(".nav");$(".nav-toggle a").on("click",function(){t.hasClass("nav-open")?t.removeClass("nav-open"):t.addClass("nav-open")})},sliders:function(){$(".slider-home").slick({slidesToShow:1,slidesToScroll:1,arrows:!1,dots:!0,autoplay:!0,autoplaySpeed:2e3}),$(".slider-single").slick({slidesToShow:1,slidesToScroll:1,arrows:!0,dots:!0,fade:!1,prevArrow:'<button type="button" class="slick-prev"><i class="fa fa-chevron-left" aria-hidden="true"></i></button>',nextArrow:'<button type="button" class="slick-next"><i class="fa fa-chevron-right" aria-hidden="true"></i></button>'})},sortCatalog:function(){var t=$("#catalogo").isotope({getSortData:{puntos:".puntos parseInt",nombre:function(t){return $(t).find(".card-title").text().toLowerCase()}}});t.imagesLoaded().progress(function(){t.isotope("layout")}),$("#sortPuntosAsc").on("click",function(e){t.isotope({sortBy:"puntos",sortAscending:!1}),e.preventDefault()}),$("#sortPuntosDesc").on("click",function(e){t.isotope({sortBy:"puntos",sortAscending:!0}),e.preventDefault()}),$("#sortNombre").on("click",function(e){t.isotope({sortBy:"nombre",sortAscending:!0}),e.preventDefault()}),$("#filterPuntos").change(function(e){this.checked?t.isotope({filter:".disponible"}):t.isotope({filter:"*"}),e.preventDefault()})},drawChart:function(){var t=document.getElementById("myChart");if(t){console.log(t);new Chart(t,{type:"line",data:historialUsuario,options:{scales:{yAxes:[{ticks:{beginAtZero:!0}}]}}})}}};$(document).ready(myApp.init);